// * Sort Ascending and Descending
document.addEventListener('DOMContentLoaded', function () {
	var table = document.getElementById('example1');
	var headers = table.querySelectorAll('thead th');

	headers.forEach(function (header, index) {
		header.addEventListener('click', function () {
			var order = header.getAttribute('data-order') || 'asc';

			order = (order === 'asc') ? 'desc' : 'asc';
			header.setAttribute('data-order', order);

			var colIndex = index;
			var rows = Array.from(table.querySelectorAll('tbody tr'));

			rows.sort(function (a, b) {
				var valA = a.children[colIndex].textContent.trim();
				var valB = b.children[colIndex].textContent.trim();

				valA = isNaN(valA) ? valA : parseFloat(valA);
				valB = isNaN(valB) ? valB : parseFloat(valB);

				if (order === 'asc') {
					return (valA > valB) ? 1 : -1;
				} else {
					return (valA < valB) ? 1 : -1;
				}
			});

			table.querySelector('tbody').innerHTML = '';

			rows.forEach(function (row) {
				table.querySelector('tbody').appendChild(row);
			});
		});
	});

	var rowsPerPage = 10; // Jumlah data per halaman
	var currentPage = 1; // Halaman saat ini

	function updatePagination() {
		var start = (currentPage - 1) * rowsPerPage;
		var end = start + rowsPerPage;

		var rows = Array.from(table.querySelectorAll('tbody tr'));

		// Sembunyikan semua baris
		rows.forEach(function (row) {
			row.style.display = 'none';
		});

		// Tampilkan hanya baris pada rentang halaman saat ini
		rows.slice(start, end).forEach(function (row) {
			row.style.display = '';
		});
	}

	function updateTable() {
		updatePagination();
	}

	// Tambahkan event listener untuk perubahan jumlah data per halaman
	document.getElementById('showEntries').addEventListener('change', function () {
		rowsPerPage = parseInt(this.value, 10);
		currentPage = 1;
		updateTable();
	});

	// ... (script sebelumnya)

	// Tambahkan event listener untuk navigasi halaman berikutnya
	document.getElementById('nextPage').addEventListener('click', function () {
		var totalRows = table.querySelectorAll('tbody tr').length;
		var totalPages = Math.ceil(totalRows / rowsPerPage);

		if (currentPage < totalPages) {
			currentPage++;
			updateTable();
		}
	});

	// Tambahkan event listener untuk navigasi halaman sebelumnya
	document.getElementById('prevPage').addEventListener('click', function () {
		if (currentPage > 1) {
			currentPage--;
			updateTable();
		}
	});
});
